record Node(int key, Node left, Node right) {}

void preOrder(Node n, List<Integer> out) {
    if (n == null) {
        return;
    }
    out.add(n.key());
    preOrder(n.left(), out);
    preOrder(n.right(), out);
}

void main() {
    Node root = new Node(5, new Node(3, new Node(1, null, null), null), new Node(8, null, new Node(9, null, null)));
    List<Integer> out = new ArrayList<>();
    preOrder(root, out);
    IO.println(out);
}
